/** Cache-only/source boundary tests: no broker/network/database write. */
class DecisionInputCaptureAdapterTest {
    LatestAssetsService assets;PriceQueryService prices;MarketDataService market;TradingRadarService radar;StockPriceHistoryRepository histories;StockDividendHistoryRepository dividends;SrppDecisionSourceRepository ledger;UsdTwdLiveRateService fx;RadarIntradayCandlePort minutes;StockRepository masters;FundClassOverrideRepository funds;DecisionInputCaptureAdapter adapter;AssetSnapshotDto.SnapshotDetailResponse snapshot;LatestAssetsDto.Response response;LocalDate date;
    @BeforeEach void setup(){date=LocalDate.now(ZoneId.of("Asia/Taipei"));assets=mock(LatestAssetsService.class);prices=mock(PriceQueryService.class);market=mock(MarketDataService.class);radar=mock(TradingRadarService.class);histories=mock(StockPriceHistoryRepository.class);dividends=mock(StockDividendHistoryRepository.class);ledger=mock(SrppDecisionSourceRepository.class);fx=mock(UsdTwdLiveRateService.class);minutes=mock(RadarIntradayCandlePort.class);masters=mock(StockRepository.class);funds=mock(FundClassOverrideRepository.class);snapshot=mock(AssetSnapshotDto.SnapshotDetailResponse.class);AssetSnapshotDto.DepositResponse deposit=new AssetSnapshotDto.DepositResponse(1L,1L,"fixturebank","TERM_TWD","term",new BigDecimal("5000000"),new BigDecimal("5000000"),"TWD",null,null,null,"MANUAL",date);AssetSnapshotDto.FundResponse fund=new AssetSnapshotDto.FundResponse(2L,"未知分類基金","24B2",1L,"fixturebank",BigDecimal.ZERO,new BigDecimal("1000000"),BigDecimal.ONE,null,null,null,null);when(snapshot.id()).thenReturn(9L);when(snapshot.deposits()).thenReturn(List.of(deposit));when(snapshot.funds()).thenReturn(List.of(fund));when(snapshot.stocks()).thenReturn(List.of());when(snapshot.totalDeposit()).thenReturn(new BigDecimal("5000000"));when(snapshot.totalFundValue()).thenReturn(new BigDecimal("1000000"));when(snapshot.totalStockValue()).thenReturn(BigDecimal.ZERO);var live=new StockPriceService.LiveAssetsResponse(9L,date.toString(),new BigDecimal("32"),new BigDecimal("5000000"),new BigDecimal("1000000"),BigDecimal.ZERO,new BigDecimal("6000000"),List.of(),true,false,false,null);response=new LatestAssetsDto.Response(Instant.now(),"CURRENT",true,Map.of(),snapshot,live);when(assets.getLatestForOwner(7)).thenReturn(response);when(market.isTwTradingDayCachedOnly(any())).thenReturn(Optional.of(true));when(prices.getLiveBatch(any(),any())).thenReturn(Map.of());when(prices.getEtfNavBatch(any())).thenReturn(Map.of());when(ledger.ledger(eq(7L),any(),any())).thenReturn(JsonNodeFactory.instance.arrayNode());when(masters.findAllByCodeIn(any())).thenReturn(List.of());when(funds.findAllById(any())).thenReturn(List.of(new FundClassOverride("未知分類基金","BOND",null,null)));when(minutes.read(any(),any(),any())).thenReturn(Map.of());adapter=new DecisionInputCaptureAdapter(assets,prices,market,radar,histories,dividends,ledger,fx,minutes,new DecisionPolicyAuthority(),new ObjectMapper().findAndRegisterModules(),masters,funds);}
    DecisionRequest request(){return new DecisionRequest(null,date,"09:05",DailyDecisionCalculatorTest.POLICY.bundleHash(),"b".repeat(64));}
    @Test void canonicalFundOverrideIsIncludedAndRawSourceFrozenBeforeMinuteFrame(){var f=adapter.capture(7,request(),List.of());assertThat(f.facts().bondValue()).isEqualByComparingTo("1000000");assertThat(f.input().path("sources").path("classifications").path("fundOverrideRows").get(0).path("assetClass").asText()).isEqualTo("BOND");var order=inOrder(assets,masters,funds,minutes);order.verify(assets).getLatestForOwner(7);order.verify(masters).findAllByCodeIn(any());order.verify(funds).findAllById(any());order.verify(minutes).read(any(),eq(date),eq(f.facts().capturedAt()));assertThat(f.facts().capturedAt()).isAfterOrEqualTo(response.generatedAt());ObjectNode copy=f.input();copy.removeAll();assertThat(f.input().has("sources")).isTrue();}
    @Test void wrongQuoteAndNavSelectorAreFrozenAsUnavailable(){var key=new PriceQueryService.PriceKey("00719B","台股");PriceQueryService.LivePrice wrong=mock(PriceQueryService.LivePrice.class);when(wrong.stockCode()).thenReturn("00865B");when(wrong.market()).thenReturn("台股");when(wrong.closed()).thenReturn(false);when(prices.getLiveBatch(any(),any())).thenReturn(Map.of(key,Optional.of(wrong)));when(prices.getEtfNavBatch(any())).thenReturn(Map.of(key,Optional.of(new PriceQueryService.EtfNav("00697B","台股",BigDecimal.TEN,BigDecimal.ZERO,date.toString(),"FUBON"))));var f=adapter.capture(7,request(),List.of());assertThat(f.facts().symbols().get("00719B").quote()).isNull();assertThat(f.sourceVector().path("quote:00719B").path("validation").asText()).isEqualTo("UNAVAILABLE");assertThat(f.input().path("sources").path("quote:00719B").path("rawNav").path("stockCode").asText()).isEqualTo("00697B");}
    @Test void staleQuoteFxDailyAndPartialBookCannotClaimVerifiedSources(){var key=new PriceQueryService.PriceKey("00719B","台股");PriceQueryService.LivePrice q=new PriceQueryService.LivePrice("00719B","fixture","台股",BigDecimal.TEN,BigDecimal.ONE,null,null,null,null,null,null,null,600000L,date.toString(),Instant.now().minusSeconds(600).toString(),false,"FUBON","LIVE");when(prices.getLiveBatch(any(),any())).thenReturn(Map.of(key,Optional.of(q)));var book=mock(QuoteDetailDto.Response.class);when(book.stockCode()).thenReturn("00719B");when(book.market()).thenReturn("台股");when(book.available()).thenReturn(true);when(book.marketStatus()).thenReturn("OPEN");when(book.levels()).thenReturn(List.of());when(market.getQuoteDetail("00719B","台股")).thenReturn(book);var f=adapter.capture(7,request(),List.of());for(String keyName:List.of("quote:00719B","book:00719B","fx","daily:00719B"))assertThat(f.sourceVector().path(keyName).path("validation").asText()).isEqualTo("UNAVAILABLE");assertThat(f.input().path("sources").path("quote:00719B").path("rawVolumeUnit").asText()).isEqualTo("SHARES");assertThat(f.facts().symbols().get("00719B").quote().volume()).isEqualTo(600);}
    @Test void duplicateFundsAndNonTransitNegativeDepositsFailL0BeforeOtherSources(){var duplicate=snapshot.funds().getFirst();when(snapshot.funds()).thenReturn(List.of(duplicate,duplicate));assertThatThrownBy(()->adapter.capture(7,request(),List.of())).isInstanceOf(SrppCaptureProblem.class);verifyNoInteractions(prices,minutes,ledger,masters,funds);}
    @Test void negativeNonTransitDepositFailsL0(){var bad=new AssetSnapshotDto.DepositResponse(1L,1L,"bank","TERM_TWD","term",BigDecimal.ONE.negate(),BigDecimal.ONE.negate(),"TWD",null,null,null,"MANUAL",date);when(snapshot.deposits()).thenReturn(List.of(bad));assertThatThrownBy(()->adapter.capture(7,request(),List.of())).isInstanceOf(SrppCaptureProblem.class);verifyNoInteractions(prices,minutes,ledger,masters,funds);}
    @Test void productionShapedTwdAndTransitPayableDepositsPassL0(){var term=new AssetSnapshotDto.DepositResponse(1L,1L,"bank","定存","定存",new BigDecimal("5004775"),null,"TWD",null,null,null,"MANUAL",null);var payable=new AssetSnapshotDto.DepositResponse(3L,2L,"card","信用卡待付款","信用卡待付款",new BigDecimal("-4775"),null,"TRANSIT_TWD",null,null,null,"MANUAL",null);when(snapshot.deposits()).thenReturn(List.of(term,payable));var f=adapter.capture(7,request(),List.of());assertThat(f.facts().capturedAt()).isAfterOrEqualTo(response.generatedAt());}
    @Test void negativeDepositNeedsTransitCurrencyNotTransitLabelAndUsdNeedsOriginalAmount(){var labelOnly=new AssetSnapshotDto.DepositResponse(1L,1L,"bank","TRANSIT_TWD","label",new BigDecimal("-1"),null,"TWD",null,null,null,"MANUAL",null);when(snapshot.deposits()).thenReturn(List.of(labelOnly));assertThatThrownBy(()->adapter.capture(7,request(),List.of())).isInstanceOf(SrppCaptureProblem.class);var usd=new AssetSnapshotDto.DepositResponse(1L,1L,"bank","美元活存","usd",new BigDecimal("5000000"),null,"USD",null,null,null,"MANUAL",null);when(snapshot.deposits()).thenReturn(List.of(usd));assertThatThrownBy(()->adapter.capture(7,request(),List.of())).isInstanceOf(SrppCaptureProblem.class);verifyNoInteractions(prices,minutes,ledger,masters,funds);}
    @Test void radarCaptureAlwaysUsesExplicitOwnerAndNeverRequestScopedSelector(){adapter.capture(7,request(),List.of());for(String code:new DecisionPolicyAuthority().policy().symbols())verify(radar).getStockDetailForOwner(7,code,"台股");verify(radar,never()).getStockDetail(anyString(),anyString());}
    @Test void sameSymbolAcrossMarketsNeverAddsUsHoldingToTaiwanBondValue(){
        var tw=mock(AssetSnapshotDto.StockResponse.class);var us=mock(AssetSnapshotDto.StockResponse.class);
        when(tw.id()).thenReturn(11L);when(us.id()).thenReturn(12L);for(var holding:List.of(tw,us)){when(holding.stockCode()).thenReturn("00719B");when(holding.shares()).thenReturn(BigDecimal.ONE);when(holding.currentValue()).thenReturn(BigDecimal.TEN);}when(tw.market()).thenReturn("台股");when(us.market()).thenReturn("美股");when(snapshot.stocks()).thenReturn(List.of(tw,us));when(snapshot.totalStockValue()).thenReturn(new BigDecimal("20"));
        var twLive=new StockPriceService.LiveStockItem("00719B","tw","台股",BigDecimal.ONE,BigDecimal.TEN,BigDecimal.TEN,false,date.toString(),null,null,null,"LIVE",11L,"FUBON",date.toString(),"TARGET_SESSION_PRICE",Instant.now());
        var usLive=new StockPriceService.LiveStockItem("00719B","us","美股",BigDecimal.ONE,BigDecimal.TEN,BigDecimal.TEN,false,date.toString(),null,null,null,"LIVE",12L,"FUBON",date.toString(),"TARGET_SESSION_PRICE",Instant.now());
        var live=new StockPriceService.LiveAssetsResponse(9L,date.toString(),new BigDecimal("32"),new BigDecimal("5000000"),new BigDecimal("1000000"),new BigDecimal("20"),new BigDecimal("6000020"),List.of(twLive,usLive),true,false,false,null);when(assets.getLatestForOwner(7)).thenReturn(new LatestAssetsDto.Response(response.generatedAt(),"CURRENT",true,Map.of(),snapshot,live));
        when(masters.findAllByCodeIn(any())).thenReturn(List.of(Stock.builder().code("00719B").market("台股").assetClass("BOND").build(),Stock.builder().code("00719B").market("美股").assetClass("STOCK").build()));
        var frozen=adapter.capture(7,request(),List.of());assertThat(frozen.facts().symbols().get("00719B").currentValue()).isEqualByComparingTo("10");assertThat(frozen.facts().bondValue()).isEqualByComparingTo("1000010");
    }
    @Test void unknownFundNameCannotGuessBondAndBlocksCapacityWithNamedMissing(){
        when(funds.findAllById(any())).thenReturn(List.of());var f=adapter.capture(7,request(),List.of());assertThat(f.facts().bondValue()).isEqualByComparingTo("0");assertThat(f.facts().symbols().get("00719B").valuation().status()).isEqualTo("UNAVAILABLE");
        assertThat(f.sourceVector().path("classifications").path("validation").asText()).isEqualTo("UNAVAILABLE");assertThat(f.input().path("sources").path("classifications").path("missing")).extracting(JsonNode::asText).contains("FUND_CLASSIFICATION_UNAVAILABLE:未知分類基金");
    }
    @Test void fxSourceFutureAndFrameAgeCannotPass(){Instant at=Instant.now();var future=new UsdTwdLiveRateService.LiveRate("USD/TWD","USD","TWD",date,new BigDecimal("32"),new BigDecimal("32"),"MEGA_BANK",at,at.plusSeconds(1),"ACTIVE","LIVE");assertThat(DecisionInputCaptureAdapter.fxQualified(future,date,at)).isFalse();var stale=new UsdTwdLiveRateService.LiveRate("USD/TWD","USD","TWD",date,new BigDecimal("32"),new BigDecimal("32"),"MEGA_BANK",at.minusSeconds(7),at.minusSeconds(7),"ACTIVE","LIVE");assertThat(DecisionInputCaptureAdapter.fxQualified(stale,date,at)).isFalse();}

    static final String POLICY_FUND_NAME="施羅德環球收益債券非常避險 (月配)";
    void usePolicyFundMapping() throws Exception {
        var current=new DecisionPolicyAuthority();var mapper=new ObjectMapper().findAndRegisterModules();
        ObjectNode model=(ObjectNode)mapper.readTree(current.modelBytes());model.putArray("fund_asset_classifications").addObject().put("fund_code","24B2").put("fund_name",POLICY_FUND_NAME).put("asset_class","BOND");
        String bytes=mapper.writeValueAsString(model);ObjectNode manifest=(ObjectNode)mapper.readTree(current.manifestBytes());manifest.withObject("files").put("assumptions/model_inputs.json",SrppJcs.sha256Hex(bytes));manifest.remove("POLICY_BUNDLE_SHA256");manifest.put("POLICY_BUNDLE_SHA256",SrppJcs.hash(manifest));
        adapter=new DecisionInputCaptureAdapter(assets,prices,market,radar,histories,dividends,ledger,fx,minutes,new DecisionPolicyAuthority(bytes,mapper.writeValueAsString(manifest)),mapper,masters,funds);
    }
    AssetSnapshotDto.FundResponse fund(long id,String code,String name){return new AssetSnapshotDto.FundResponse(id,name,code,1L,"fixturebank",BigDecimal.ZERO,new BigDecimal("1000000"),BigDecimal.ONE,null,null,null,null);}
    void installFunds(List<AssetSnapshotDto.FundResponse> rows){
        BigDecimal total=rows.stream().map(AssetSnapshotDto.FundResponse::currentValue).reduce(BigDecimal.ZERO,BigDecimal::add);when(snapshot.funds()).thenReturn(rows);when(snapshot.totalFundValue()).thenReturn(total);
        var live=new StockPriceService.LiveAssetsResponse(9L,date.toString(),new BigDecimal("32"),new BigDecimal("5000000"),total,BigDecimal.ZERO,new BigDecimal("5000000").add(total),List.of(),true,false,false,null);
        when(assets.getLatestForOwner(7)).thenReturn(new LatestAssetsDto.Response(response.generatedAt(),"CURRENT",true,Map.of(),snapshot,live));
    }
    @Test void exactPolicyFundIdentityRestoresCapacityWhenDbOnlyHasBondTerm() throws Exception {
        usePolicyFundMapping();installFunds(List.of(fund(2L,"24B2",POLICY_FUND_NAME)));when(funds.findAllById(any())).thenReturn(List.of(new FundClassOverride(POLICY_FUND_NAME,null,null,"LONG")));
        var captured=adapter.capture(7,request(),List.of());JsonNode classifications=captured.input().path("sources").path("classifications");
        assertThat(captured.facts().bondValue()).isEqualByComparingTo("1000000");assertThat(captured.facts().symbols().get("00719B").valuation().verified()).isTrue();
        assertThat(classifications.path("resolvedFundClasses").path(POLICY_FUND_NAME).asText()).isEqualTo("BOND");assertThat(classifications.path("resolvedFundClassSources").path("2").asText()).isEqualTo("POLICY_EXACT_IDENTITY");assertThat(classifications.path("policyFundRows").size()).isEqualTo(1);assertThat(classifications.path("fundOverrideRows").get(0).path("assetClass").isNull()).isTrue();assertThat(captured.sourceVector().path("classifications").path("validation").asText()).isEqualTo("VERIFIED");
    }
    @Test void explicitDbFundClassWinsOverPolicyAndInvalidOverrideCannotFallBack() throws Exception {
        usePolicyFundMapping();installFunds(List.of(fund(2L,"24B2",POLICY_FUND_NAME)));when(funds.findAllById(any())).thenReturn(List.of(new FundClassOverride(POLICY_FUND_NAME,"STOCK",null,null)));
        var captured=adapter.capture(7,request(),List.of());assertThat(captured.facts().bondValue()).isEqualByComparingTo("0");assertThat(captured.facts().symbols().get("00719B").valuation().verified()).isTrue();assertThat(captured.input().path("sources").path("classifications").path("resolvedFundClassSources").path("2").asText()).isEqualTo("DB_OVERRIDE");
        when(funds.findAllById(any())).thenReturn(List.of(new FundClassOverride(POLICY_FUND_NAME,"UNKNOWN",null,null)));assertThat(adapter.capture(7,request(),List.of()).facts().symbols().get("00719B").valuation().verified()).isFalse();
    }
    @Test void wrongCodeWrongNameOrSameNameDifferentHoldingNeverInheritsPolicyClass() throws Exception {
        usePolicyFundMapping();when(funds.findAllById(any())).thenReturn(List.of());
        for(var row:List.of(fund(2L,"24B2X",POLICY_FUND_NAME),fund(2L,"24B2",POLICY_FUND_NAME+" "),fund(2L,null,POLICY_FUND_NAME))){installFunds(List.of(row));var captured=adapter.capture(7,request(),List.of());assertThat(captured.facts().symbols().get("00719B").valuation().verified()).isFalse();assertThat(captured.facts().bondValue()).isEqualByComparingTo("0");}
        installFunds(List.of(fund(2L,"24B2",POLICY_FUND_NAME),fund(3L,"OTHER",POLICY_FUND_NAME)));var captured=adapter.capture(7,request(),List.of());JsonNode classification=captured.input().path("sources").path("classifications");assertThat(captured.facts().symbols().get("00719B").valuation().verified()).isFalse();assertThat(captured.facts().bondValue()).isEqualByComparingTo("1000000");assertThat(classification.path("resolvedFundClasses").has(POLICY_FUND_NAME)).isFalse();assertThat(classification.path("resolvedFundHoldingClasses").has("3")).isFalse();
    }
    @Test void captureUsesClosedRadarCompatibilityAndPreservesOfficialVeto() throws Exception {
        var mapper=new ObjectMapper().findAndRegisterModules();
        for(String version:List.of("EVIDENCE_GATE_V1","EVIDENCE_GATE_V2","EVIDENCE_GATE_V3")){
            ObjectNode raw=mapper.createObjectNode();raw.put("ruleVersion",TradingRadarRuleEngine.RULE_VERSION).put("actionPolicyVersion",version).put("generatedAt",Instant.now().minusSeconds(1).toString());ObjectNode stock=raw.putObject("stock");stock.put("stockCode","00719B").put("market","台股").put("asOfDate",date.toString()).put("quoteStatus","LIVE").put("dataComplete",true).put("action","HOLD").put("candidateAction","HOLD");stock.putObject("officialSma20Verification").put("status","CONFIRMED").put("gateApplied",false);
            when(radar.getStockDetailForOwner(7,"00719B","台股")).thenReturn(mapper.treeToValue(raw,TradingRadarDto.StockDetailResponse.class));var captured=adapter.capture(7,request(),List.of());assertThat(captured.facts().symbols().get("00719B").radar().verified()).isEqualTo(!version.equals("EVIDENCE_GATE_V3"));
            if(version.equals("EVIDENCE_GATE_V2")){
                stock.withObject("officialSma20Verification").put("status","CONFLICT");when(radar.getStockDetailForOwner(7,"00719B","台股")).thenReturn(mapper.treeToValue(raw,TradingRadarDto.StockDetailResponse.class));captured=adapter.capture(7,request(),List.of());assertThat(captured.facts().symbols().get("00719B").radar().reason()).isEqualTo("RADAR_OFFICIAL_SMA20_CONFLICT");assertThat(captured.sourceVector().path("radar:00719B").path("validation").asText()).isEqualTo("VERIFIED");
                stock.remove("officialSma20Verification");when(radar.getStockDetailForOwner(7,"00719B","台股")).thenReturn(mapper.treeToValue(raw,TradingRadarDto.StockDetailResponse.class));assertThat(adapter.capture(7,request(),List.of()).facts().symbols().get("00719B").radar().reason()).isEqualTo("RADAR_V2_OFFICIAL_SMA20_UNVERIFIED");
            }
        }
    }
    @Test void supportedRadarWithWrongDateOrNonLiveStatusIsUnavailable() throws Exception {
        var mapper=new ObjectMapper().findAndRegisterModules();ObjectNode raw=mapper.createObjectNode();raw.put("ruleVersion",TradingRadarRuleEngine.RULE_VERSION).put("actionPolicyVersion","EVIDENCE_GATE_V1").put("generatedAt",Instant.now().minusSeconds(1).toString());ObjectNode stock=raw.putObject("stock");stock.put("stockCode","00719B").put("market","台股").put("asOfDate",date.minusDays(1).toString()).put("quoteStatus","LIVE").put("dataComplete",true).put("action","HOLD");
        when(radar.getStockDetailForOwner(7,"00719B","台股")).thenReturn(mapper.treeToValue(raw,TradingRadarDto.StockDetailResponse.class));assertThat(adapter.capture(7,request(),List.of()).facts().symbols().get("00719B").radar().verified()).isFalse();
        stock.put("asOfDate",date.toString()).put("quoteStatus","VERIFIED_CLOSE");when(radar.getStockDetailForOwner(7,"00719B","台股")).thenReturn(mapper.treeToValue(raw,TradingRadarDto.StockDetailResponse.class));assertThat(adapter.capture(7,request(),List.of()).facts().symbols().get("00719B").radar().verified()).isFalse();
    }

}
